"use strict"; $(document).ready(function () {
    $(".upload-button").on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();

        // cari wrapper terdekat
        const wrapper = $(this).closest(".your-brand");

        // hanya klik input milik upload ini
        const input = wrapper.find(".file-upload");

        if (input.length) {
            input.trigger("click");
        }
    });

    $(".file-upload").on("change", function () {
        const input = this;

        if (!input.files || !input.files[0]) return;

        const wrapper = $(input).closest(".your-brand");
        const preview = wrapper.find(".upload-pic");

        const reader = new FileReader();
        reader.onload = function (e) {
            preview.attr("src", e.target.result);
        };
        reader.readAsDataURL(input.files[0]);
    });
}), $(document).ready(function () {
    var e = document.getElementById("dateofBirth");
    new Datepicker(e, { clearBtn: !0, allowOneSidedRange: !0 })
}), $(document).ready(function () {
    $('[data-action-target="#acSecctingsActionMessage"]').click(function (e) {
        e.preventDefault(); const t = Swal.mixin({ customClass: { confirmButton: "btn btn-success m-1", cancelButton: "btn btn-danger m-1" }, buttonsStyling: !1 });
        t.fire({ title: "Delete Account", text: "You want to delete this account!!!", icon: "warning", showCancelButton: !0, confirmButtonText: "Yes, Delete it!", cancelButtonText: "No, cancel!", reverseButtons: !0 }).then(e => { e.value ? t.fire("Deleted!", "Account Deleted Successfully.", "success") : e.dismiss === Swal.DismissReason.cancel && t.fire("Cancelled", "Your imaginary file is safe :)", "error") })
    })
});